sys_script.script:
//MSSCUSTODY-3414 - Created this business rule to set bulk task type and retrieve the related list in Client Script - MSSCustodyShowBulkTaskRelatedList	
(function executeRule(current, previous /*null when async*/ ) {

    //MSSCUSOTDY-3282 : This code will extract data and load in scratchpad for further use
    new x_hsb11_mss_c_proc.MSSCustodyBulkUtils().gettaskdetails(current.sys_id, current.owning_business);

    g_scratchpad.blkTskRelated = current.bulk_task_type;
    g_scratchpad.bulktype = current.bulk_type;
    g_scratchpad.loggeduserID = gs.getUserID(); //MSSCUSTODY-3978
    g_scratchpad.host = gs.getProperty("glide.servlet.uri"); //MSSCUSTODY - 3992
    g_scratchpad.name = current.assigned_to.first_name; //MSSCUSTODY - 3992
    g_scratchpad.time = GlideDateTime().getDisplayValue(); //MSSCUSTODY - 3992
    g_scratchpad.usr_access = gs.getUser().isMemberOf(current.assignment_group.parent.toString());
    g_scratchpad.active_trades = current.active_trade_count; //MSSCUSTODY-5407 & MSSCUSTODY-5580
    //MSSCUSTODY-4966
    g_scratchpad.ownB = current.owning_business; //MSSCUSTODY-4901
    g_scratchpad.rCodeDCCUK = gs.getProperty('x_hsb11_mss_c_proc.ReasonCodeForGCSDccUK'); //MSSCUSTODY-4901
    g_scratchpad.rCodeGCCUK = gs.getProperty('x_hsb11_mss_c_proc.ReasonCodeForGCSGcUK'); //MSSCUSTODY-4901
    g_scratchpad.rCodeDCCEU = gs.getProperty('x_hsb11_mss_c_proc.ReasonCodeForGCSDccEU');
    g_scratchpad.rCodeGCCEU = gs.getProperty('x_hsb11_mss_c_proc.ReasonCodeForGCSGcEU');
    g_scratchpad.hasWorkedAsMaker = false; //MSSCUSTODY - 5250
    var manager = gs.hasRole('x_hsb11_mss_custod.custody_manager');
    var maker_access = new x_hsb11_mss_c_proc.MSSCustodyBulkUtils().evalMakerAccess();

    // Count the number of tasks in the same case with trade_task_type as Maker
    var makerTaskCount = 0; // Initialize the count variable
    var makerTaskQuery = new GlideAggregate("x_hsb11_mss_c_proc_mss_custody_task");
    makerTaskQuery.addEncodedQuery('bulk_id.sys_id=' + current.sys_id + '^trade_task_type=Maker^active=false');
    makerTaskQuery.groupBy('trade_task_type');
    makerTaskQuery.addAggregate('COUNT', 'number'); // Count the number of tasks
    makerTaskQuery.query();
    while (makerTaskQuery.next()) {
        makerTaskCount = parseInt(makerTaskQuery.getAggregate('COUNT', 'number')); // Get the count
    }
    g_scratchpad.bulkMakerTaskCount = makerTaskCount;
    //MSSCUSTODY-4192
    var grbulk = current;

    // if (current.lock == false && (current.state == '1' || current.state == '2')) {
    //     if (gs.getUser().isMemberOf(current.assignment_group.parent.toString()) && ((grbulk.bulk_task_type == 'Checker') || (grbulk.bulk_task_type == 'Maker'))) {
    //         grbulk.assigned_to = gs.getUserID();
    //         grbulk.lock = true; // MSSCUSTODY - 3992
    //         grbulk.locktime = GlideDateTime().getDisplayValue(); // MSSCUSTODY - 3992           
    //         grbulk.update();
    //     }
    // }

    //MSSCUSTODY-5250
    if (current.lock == false && (current.state == '1' || current.state == '2') && gs.getUser().isMemberOf(current.assignment_group.parent.toString()) && ((grbulk.bulk_task_type == 'Checker') || (grbulk.bulk_task_type == 'Maker'))) {

        if (grbulk.bulk_task_type == 'Checker') {
            if (grbulk.current_maker_assignee == gs.getUserID()) { //If current user has been a Maker before
                g_scratchpad.hasWorkedAsMaker = true;
                return;
            }

            grbulk.assigned_to = gs.getUserID();
            grbulk.lock = true; // MSSCUSTODY - 3992
            grbulk.locktime = GlideDateTime().getDisplayValue(); // MSSCUSTODY - 3992           
            grbulk.update();

        } else {
            grbulk.assigned_to = gs.getUserID();
            grbulk.lock = true; // MSSCUSTODY - 3992
            grbulk.locktime = GlideDateTime().getDisplayValue(); // MSSCUSTODY - 3992           
            grbulk.update();
        }

    } else if (current.lock == true && current.state == '2' && gs.getUser().isMemberOf(current.assignment_group.parent.toString()) && grbulk.trade_task_type == 'Checker' && grbulk.current_maker_assignee == gs.getUserID()) {
        g_scratchpad.hasWorkedAsMaker = true;
        return;
    }

    var created = new GlideDateTime(current.sys_created_on); // for defect 3717, checking if the bulk is created within 1 minute of loading it.    
    var currentTime = new GlideDateTime();
    currentTime.addSeconds(-60);
    if (created > currentTime)
        g_scratchpad.created_time = true;
    else
        g_scratchpad.created_time = false;


    // MSSCUSTODY-5855
    var glideTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
    glideTask.addQuery('bulk_id', current.sys_id);
    glideTask.query();
    if (glideTask.next()) {
        gs.getSession().putClientData('siteCode', glideTask.trade_id.trade_id.slice(0, 7));
    }

    //-----------------------------GC HK-Validations - MSSCUSTODY-7894------------------------------

    g_scratchpad.fx_bulk = false;
    g_scratchpad.bCi_bulk = false;


    var tradeGr = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_task");
    tradeGr.addQuery('bulk_id', current.sys_id);
    tradeGr.query();
    while (tradeGr.next()) {
        if (!g_scratchpad.fx_bulk && (tradeGr.trade_id.u_fx_inst_sts != 'NA' && tradeGr.trade_id.u_fx_inst_sts != '')) {
            g_scratchpad.fx_bulk = true;
        }
        if (!g_scratchpad.bCi_bulk && (tradeGr.trade_id.pend_canc_support_indicator == 'B' || tradeGr.trade_id.pend_canc_support_indicator == 'Y')) {
            g_scratchpad.bCi_bulk = true;
        }

        if (
            g_scratchpad.fx_bulk &&
            g_scratchpad.bCi_bulk
        ) {
            break;
        }
    }
    gs.info('GC-HK Scratchpad - FX ' + g_scratchpad.fx_bulk + ' bCi- ' + g_scratchpad.bCi_bulk);

    //-----------------------------GC HK - Validations - MSSCUSTODY-7894------------------------------


    //------------------------------------Recreated Checker Flag ------------------------------------MSSCUSTODY - 7539

    var taskGr = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
    taskGr.addEncodedQuery('bulk_id=' + current.sys_id + '^stateIN1,2^amend_checker_decision=Amend_Recreated');
    taskGr.query();
    if (taskGr.next()) {
        g_scratchpad.reFlag = 'true';
    } else {
        g_scratchpad.reFlag = 'false';
    }

    var taskGr2 = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
    taskGr2.addEncodedQuery('bulk_id=' + current.sys_id + '^stateIN1,2^amend_checker_decision=Amend');
    taskGr2.query();
    if (taskGr2.next()) {
        g_scratchpad.reFlag2 = 'true';
    } else {
        g_scratchpad.reFlag2 = 'false';
    }

    //------------------------------------Recreated Checker Flag ------------------------------------



    // MSSCUSTODY-6106
    if (current.upload_type != '') {
        g_scratchpad.uploadType = current.upload_type;
    }


})(current, previous);
